    color: #000000 !important;
    text-shadow: none !important;
    -webkit-text-fill-color: #000000 !important;
}
/* 礼物盒丝带等装饰元素保持原有颜色 */
.gift-ig-container .gift-ribbon,
.gift-ig-container [class*="ribbon"],
.gift-ig-container [class*="bow"] {
    color: inherit !important;
    -webkit-text-fill-color: inherit !important;
}
/* 礼物盒内的按钮保持蓝色 */
.gift-ig-container button,
.gift-ig-container a {
    color: #007aff !important;
    text-shadow: none !important;
}
/* ===== 图片消息卡片 - 强制黑色文字 ===== */
.msg-image-wrapper,
.msg-image-wrapper *,
.msg-image-wrapper span,
.msg-image-wrapper div,
.msg-image-wrapper p,
.msg-image-caption,
.image-caption,
.image-description,
[class*="image-caption"],
[class*="image-description"],
[class*="img-caption"] {
    color: #000000 !important;
    text-shadow: none !important;
    -webkit-text-fill-color: #000000 !important;
}
/* 图片消息内的按钮/链接保持蓝色 */
.msg-image-wrapper button,
.msg-image-wrapper a,
.msg-image-wrapper [role="button"] {
    color: #007aff !important;
    text-shadow: none !important;
    -webkit-text-fill-color: #007aff !important;
}
/* 图片描述文字添加半透明白色背景确保可读 */
.image-description,
.msg-image-caption,
[class*="caption"] {
    background: rgba(255, 255, 255, 0.85) !important;
    padding: 4px 8px !important;
    border-radius: 8px !important;
    display: inline-block !important;
}
/* ===== 模拟截图卡片/文字长图 - 强制黑色文字 ===== */
.msg-sim-card,
.msg-sim-card *,
.msg-sim-card span,
.msg-sim-card div,
.msg-sim-card p,
.sim-card-content,
.sim-card-text,
[class*="sim-card"],
[class*="screenshot"] {
    color: #000000 !important;
    text-shadow: none !important;
    -webkit-text-fill-color: #000000 !important;
}
/* ===== 边缘光晕层 - 极淡，勾勒边框 ===== */
.bubble-me-custom::before,
.bubble-them-custom::before {
    content: "";
    position: absolute;
    inset: -1px;
    background: radial-gradient(
        circle at 30% 20%,
        rgba(255, 255, 255, 0.08) 0%,
        rgba(255, 255, 255, 0) 70%
    );
    border-radius: 25px;
    pointer-events: none;
    z-index: -1;
}
/* 内发光层 - 极淡 */
.bubble-me-custom::after,
.bubble-them-custom::after {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(
        circle at 70% 80%,
        rgba(255, 255, 255, 0.04) 0%,
        rgba(255, 255, 255, 0) 70%
    );
    border-radius: 24px;
    pointer-events: none;
    z-index: 1;
}
/* ===== 时间戳 ===== */
.bubble-me-custom .msg-wa-time,
.bubble-them-custom .msg-wa-time,
.msg-wa-meta {
    color: rgba(255, 255, 255, 0.6) !important;
    font-size: 10px !important;
    text-shadow: none !important;
}
/* ===== 已读勾勾 ===== */
.msg-wa-checks {
    color: rgba(255, 255, 255, 0.5) !important;
    filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.2));
}
.msg-wa-checks.read {
    color: rgba(255, 255, 255, 0.75) !important;
    filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.3));
}
/* ===== 语音波形 ===== */
.bubble-me-custom .voice-wave-bar-active,
.bubble-them-custom .voice-wave-bar-active {
    background-color: #ffffff !important;
    box-shadow: 0 0 2px rgba(255, 255, 255, 0.4) !important;
}
.bubble-me-custom .voice-wave-bar-inactive,
.bubble-them-custom .voice-wave-bar-inactive {
    background-color: rgba(255, 255, 255, 0.3) !important;
}
/* ===== 翻译按钮/区块 ===== */
.bubble-me-custom .translation-btn,
.bubble-them-custom .translation-btn {
    color: rgba(255, 255, 255, 0.75) !important;
    text-shadow: 0 0 1px rgba(255, 255, 255, 0.2) !important;
}
.bubble-me-custom .translation-text,
.bubble-them-custom .translation-text {
    color: rgba(255, 255, 255, 0.8) !important;
    background: rgba(255, 255, 255, 0.06) !important;
    border-radius: 12px !important;
    padding: 6px 10px !important;
    text-shadow: none !important;
}
/* ===== 回复引用区块 ===== */
.bubble-me-custom .reply-block,
.bubble-them-custom .reply-block {
    background: rgba(255, 255, 255, 0.05) !important;
    border-left: 2px solid rgba(255, 255, 255, 0.45) !important;
    border-radius: 12px !important;
    padding: 6px 10px !important;
}
.bubble-me-custom .reply-name,
.bubble-them-custom .reply-name {
    color: rgba(255, 255, 255, 0.85) !important;
    text-shadow: 0 0 1px rgba(255, 255, 255, 0.25) !important;
}
.bubble-me-custom .reply-preview,
.bubble-them-custom .reply-preview {
    color: rgba(255, 255, 255, 0.6) !important;
}
/* ===== 代码块 ===== */
.bubble-me-custom code,
.bubble-them-custom code {
    background: rgba(255, 255, 255, 0.08) !important;
    color: #f0f0f0 !important;
    border-radius: 6px !important;
    padding: 2px 6px !important;
    text-shadow: none !important;
}
/* ===== 气泡连发圆角 ===== */
.bubble-me-custom.first {
    border-radius: 24px 24px 8px 24px !important;
}
.bubble-me-custom.mid {
    border-radius: 24px 8px 8px 24px !important;
}
.bubble-me-custom.last {
    border-radius: 24px 8px 24px 24px !important;
}
.bubble-them-custom.first {
    border-radius: 24px 24px 24px 8px !important;
}
.bubble-them-custom.mid {
    border-radius: 8px 24px 24px 8px !important;
}
.bubble-them-custom.last {
    border-radius: 8px 24px 24px 24px !important;
}
/* ===== 整体滤镜 - 极淡 ===== */
.bubble-me-custom,
.bubble-them-custom {
    filter: drop-shadow(0 0 1px rgba(255, 255, 255, 0.15));
}
/* 深色背景适配 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .bubble-them-custom {
    backdrop-filter: blur(18px) saturate(185%) !important;
    -webkit-backdrop-filter: blur(18px) saturate(185%) !important;
}
